try:
    print('>>> f = map')
    print('>>> x = slice(0)')
    print('>>> y = bytearray()')
    print('>>> f(x, y)')
    f = map
    x = slice(0)
    y = bytearray()
    print(f(x, y))
except Exception as e:
    print(type(e), ':', e)
print()
